// AI 스타트업 (bubble/9 기호의 파티, user 2026-11-05): the marks of the AI boom's companies — the labs, the GPU clouds
// and inference APIs, the frameworks, the coding agents, the video/image/voice generators, the AI search and work
// apps, China's and Asia's model companies and YC's AI batches — each its real mark as shipped, struck as a raised
// enamel/metal badge without backing: flat top (HEIGHT), rounded edge (BEVEL), and in a multi-colour mark each colour
// field its own layer and paint, fields lying on an earlier field (an eye on a face) a fine step up (INLAY).
//
// The list was built from: Forbes AI 50 2024 and 2025 (https://www.forbes.com/lists/ai50/, with Sequoia and Meritech;
// 2025 summary https://insights.tryspecter.com/forbes-ai-50-2025/), CB Insights AI 100 2025
// (https://www.cbinsights.com/research/report/artificial-intelligence-top-startups-2025/, summary
// https://www.deeplearning.ai/the-batch/ai-agents-and-infrastructure-dominate-cb-insights-top-100-ai-startups-list),
// a16z's Top 100 Gen AI Consumer Apps, 4th and 5th editions (https://a16z.com/100-gen-ai-apps-4/,
// https://a16z.com/100-gen-ai-apps-5/), Menlo Ventures' 2025 State of Generative AI in the Enterprise
// (https://menlovc.com/perspective/2025-the-state-of-generative-ai-in-the-enterprise/), TechCrunch's "49 US AI start-ups
// that raised $100M or more in 2025" (https://techcrunch.com/2025/11/26/here-are-the-49-us-ai-startups-that-have-raised-100m-or-more-in-2025/),
// Crunchbase News' 2025 AI funding round-ups (https://news.crunchbase.com/ai/big-funding-trends-charts-eoy-2025/,
// https://news.crunchbase.com/venture/largest-funding-rounds-genai-defense-eoy-2025/), Bessemer's State of AI 2025
// (https://www.bvp.com/atlas/the-state-of-ai-2025), Air Street's State of AI Report 2025 (https://www.stateof.ai/),
// and Y Combinator's company directory filtered to generative AI (https://www.ycombinator.com/companies/industry/generative-ai;
// batches as listed there, e.g. https://www.ycombinator.com/companies/ollama) — then kept only the companies whose real
// mark exists exactly in the local sources: @lobehub/icons-static-svg 1.102 (MIT; its <name>-color.svg for the real
// colours, every path, fill and gradient carried over) and simple-icons (CC0 path data, its hex for the colour). The
// marks remain their owners'. Not in the existing 테크 로고 group's marks (Claude, OpenAI, Gemini, DeepSeek …).
//
// The layers were generated from the SVGs (scratchpad ai-gen/gen.ts): even-odd paths made non-zero by reversing their
// holes, arcs/quadratics as cubics, coordinates to 0.01 of the 24 box. Approximations: an elliptical radial gradient
// (Lovable) as its mean-radius circle, a translucent fill (none kept here) mixed with white.
//
// Left out for lack of an exact symbol mark in these sources: OpenAI, Gemini, DeepSeek (테크 로고 has them); Scale AI,
// CoreWeave, Pinecone, Weaviate, Glean, Harvey, Sierra, Decagon, Abridge, OpenEvidence, Character.ai, Genspark, Gamma,
// Jasper, Synthesia, HeyGen, Captions, Descript, Otter, Granola, Cognition (Devin's mark is kept), Factory, Augment,
// Bolt (StackBlitz's bolt is the parent's mark, Bolt's own is a wordmark), Safe Superintelligence, Thinking Machines,
// Figure, Physical Intelligence, Skild, 1X, Apptronik, Agility (no robotics marks at all, so no 로봇·피지컬 subgroup),
// Vapi, Cartesia, E2B, Browserbase. Dropped after checking: AI21 and TII (wordmarks), Unstructured (wordmark tile),
// Nous Research (an engraved illustration, unreadable at 40 px), Fish Audio (hairline bars with translucent fills).

import type { CatalogueGroup, CatalogueKind, Paint } from "./types.ts";

/** The mark's height: a struck enamel badge without its backing, flat on top. */
const HEIGHT = 0.22;
const BEVEL = 0.04;
/** A colour field lying on an earlier field of the mark (an eye on a face, a fill in a frame): a step up, finely edged. */
const INLAY = 0.03;
const INLAY_BEVEL = 0.015;

/** [path data, paint, 1 when it lies on an earlier layer]. */
type Layer = readonly [string, Paint, 1?];
type Mark = { readonly id: string; readonly label: string; readonly sub: string; readonly source: string; readonly viewBox: readonly [number, number, number, number]; readonly outline?: number; readonly layers: readonly Layer[] };

