/**
 * Left out (user, 2026-11-05: marks against the object rules go): hairline, wireframe and dot-grid marks with no
 * volume to blow up (docs/agent-onboarding.md, object party rules). Their data stays above for the record.
 */
const LEFT_OUT = new Set([
  "aiReka", "aiArcee", "aiDeepCogito", "aiCerebras", "aiSambaNova", "aiLambda", "aiModal", "aiFireworks", "aiReplicate",
  "aiDeepInfra", "aiFeatherless", "aiWandb", "aiExa", "aiTavily", "aiVoyage", "aiV0", "aiPoolside", "aiMidjourney",
  "aiPerplexity", "aiZhipu", "aiMiniMax", "aiStepFun", "aiSakana", "aiOllama", "aiLangfuse",
]);

const kinds: CatalogueKind[] = MARKS.filter((mark) => !LEFT_OUT.has(mark.id)).map((mark) => ({
  id: mark.id,
  label: mark.label,
  feed: mark.label,
  sub: mark.sub,
  source: mark.source,
  make: {
    source: "relief",
    viewBox: mark.viewBox,
    layers: mark.layers.map(([d, paint, inlay]) =>
      inlay ? { d, height: INLAY, bevel: INLAY_BEVEL, paint } : { d, height: HEIGHT, bevel: BEVEL, paint, ...(mark.outline ? { stroke: mark.outline } : {}) },
    ),
  },
}));

const group: CatalogueGroup = { id: "ai", label: "AI 스타트업", kinds };
export default group;
